+// ======================================================
+// UPDATE DOCTOR ATTENDANCE
+// ======================================================

+const updateDoctorAttendance = async (req, res) => {
+  try {
+    const { hospitalId, doctorId } = req.params;
+    const {
+      action,
+      reason = "",
+      start,
+      end,
+    } = req.body;
+
+    // --------------------------------------------------
+    // VALIDATION
+    // --------------------------------------------------
+
+    if (!hospitalId) {
+      return res.status(400).json({
+        success: false,
+        message: "Hospital ID is required",
+      });
+    }
+
+    if (!doctorId) {
+      return res.status(400).json({
+        success: false,
+        message: "Doctor ID is required",
+      });
+    }
+
+    if (!action) {
+      return res.status(400).json({
+        success: false,
+        message: "Attendance action is required",
+      });
+    }
+
+    const allowedActions = [
+      "check-in",
+      "check-out",
+      "start-break",
+      "end-break",
+      "save-hours",
+    ];
+
+    if (!allowedActions.includes(action)) {
+      return res.status(400).json({
+        success: false,
+        message: "Invalid attendance action",
+      });
+    }
+
+    // --------------------------------------------------
+    // CHECK HOSPITAL
+    // --------------------------------------------------
+
+    const hospital = await Hospital.findById(hospitalId);
+
+    if (!hospital) {
+      return res.status(404).json({
+        success: false,
+        message: "Hospital not found",
+      });
+    }
+
+    // --------------------------------------------------
+    // CHECK DOCTOR
+    // --------------------------------------------------
+
+    const doctor = await Doctor.findOne({
+      _id: doctorId,
+      hospital: hospitalId,
+    });
+
+    if (!doctor) {
+      return res.status(404).json({
+        success: false,
+        message: "Doctor not found for this hospital",
+      });
+    }
+
+    // --------------------------------------------------
+    // CHECK IN
+    // --------------------------------------------------
+
+    if (action === "check-in") {
+      doctor.available = true;
+      doctor.attendanceStatus = "Present";
+      doctor.isOnBreak = false;
+      doctor.breakReason = "";
+
+      doctor.lastCheckIn = new Date();
+
+      await doctor.save();
+
+      return res.json({
+        success: true,
+        message: `${doctor.name} checked in successfully`,
+        doctor,
+      });
+    }
+
+    // --------------------------------------------------
+    // CHECK OUT
+    // --------------------------------------------------
+
+    if (action === "check-out") {
+      doctor.available = false;
+      doctor.attendanceStatus = "Absent";
+      doctor.isOnBreak = false;
+      doctor.breakReason = "";
+
+      doctor.lastCheckOut = new Date();
+
+      await doctor.save();
+
+      return res.json({
+        success: true,
+        message: `${doctor.name} checked out successfully`,
+        doctor,
+      });
+    }
+
+    // --------------------------------------------------
+    // START BREAK
+    // --------------------------------------------------
+
+    if (action === "start-break") {
+      doctor.available = false;
+      doctor.attendanceStatus = "On Break";
+      doctor.isOnBreak = true;
+      doctor.breakReason = reason || "Break";
+
+      await doctor.save();
+
+      return res.json({
+        success: true,
+        message: `${doctor.name} is now on break`,
+        doctor,
+      });
+    }
+
+    // --------------------------------------------------
+    // END BREAK
+    // --------------------------------------------------
+
+    if (action === "end-break") {
+      doctor.available = true;
+      doctor.attendanceStatus = "Present";
+      doctor.isOnBreak = false;
+      doctor.breakReason = "";
+
+      await doctor.save();
+
+      return res.json({
+        success: true,
+        message: `${doctor.name} break ended`,
+        doctor,
+      });
+    }
+
+    // --------------------------------------------------
+    // SAVE WORKING HOURS
+    // --------------------------------------------------
+
+    if (action === "save-hours") {
